export const meta = {
  name: 'code-loop',
  description: 'Native code review with fixes applied, gated by the test suites, until the diff reviews clean — then the PR',
  whenToUse: 'After the UI and functional fixes of a branch have converged and before its PR; the last stage of build-idea. Unattended: findings the reviewer can fix are applied and gated, the rest become PR comments for the human.',
  phases: [
    { title: 'Review', detail: '/code-review high --fix, then the gates' },
    { title: 'PR', detail: 'open through prm; the human merges' },
  ],
}
// Code generated by tools/gen-workflows from workflows-src/flows/code-loop.js. DO NOT EDIT.
// Edit the flow or its lib/ fragments under workflows-src/, then `go run ./tools/gen-workflows`.
// ---- lib/preamble.js — the lines every agent prompt starts with
// Agents already carry the repo's CLAUDE.md; these name only what a
// workflow stage needs beyond it. Keep it to contracts, never procedure —
// procedure is served by the vitrinka server (`docs {topic}`) and the CLI's
// `--help`.
const PREAMBLE = [
  'You are one stage of a vitrinka workflow. Your final text IS the return value: return raw data for the schema, never a human-facing report.',
  'Work in the current checkout (a worktree). Never switch branches, never stash, never touch the main checkout.',
  'Apps and test suites run where the repo\'s CLAUDE.md says — a worktree\'s devbox when one exists (`devbox run -- \'<cmd>\'`), otherwise locally; say which in `problems` when you had to fall back.',
  'Every vitrinka board/task link you return is the server-returned `url`, verbatim — never composed, never shortened.',
  'Browser work: onyx `browser_start(session: $CLAUDE_CODE_SESSION_ID)` first, headless, then playwright; screenshots land in `.vitrinka/mcp/` or the capture root you were given, never the repo root.',
  'When a door refuses (4xx with a diagnosis), apply the corrected call it names once; a second refusal is a `problems` entry, not a workaround.',
].join('\n')

function withPreamble(prompt) {
  return PREAMBLE + '\n\n' + prompt
}
// ---- lib/schemas.js — structured-output schemas shared by the flows
const ROUTE = {
  type: 'object',
  properties: {
    path: { type: 'string' },
    title: { type: 'string' },
    file: { type: 'string', description: 'repo-relative implementing file' },
    auth: { type: 'string', description: 'none | user | admin | <role>' },
    setup: { type: 'string', description: 'how to reach it with data on screen (seed, fixture, deep link)' },
  },
  required: ['path', 'title'],
}

const TERRAIN_SCHEMA = {
  type: 'object',
  properties: {
    projectType: { type: 'string', enum: ['web', 'expo', 'cli', 'other'] },
    routes: { type: 'array', items: ROUTE },
    journeys: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          title: { type: 'string' },
          steps: { type: 'array', items: { type: 'string' } },
          roles: { type: 'array', items: { type: 'string' } },
        },
        required: ['title', 'steps'],
      },
    },
    extendPoints: { type: 'array', items: { type: 'object', properties: { what: { type: 'string' }, file: { type: 'string' }, why: { type: 'string' } }, required: ['what', 'file'] } },
    duplicationRisks: { type: 'array', items: { type: 'object', properties: { risk: { type: 'string' }, existing: { type: 'string' } }, required: ['risk', 'existing'] } },
    openQuestions: { type: 'array', items: { type: 'string' } },
    terrainUrl: { type: 'string', description: 'server-returned url of the pushed terrain artifact, empty when not pushed' },
    boardUrl: { type: 'string' },
  },
  required: ['projectType', 'routes'],
}

const FINDING = {
  type: 'object',
  properties: {
    key: { type: 'string' },
    id: { type: 'integer', description: 'annotation id from the annotate receipt' },
    cardId: { type: 'integer' },
    route: { type: 'string' },
    device: { type: 'string' },
    area: { type: 'string', description: 'route, component or subsystem the fix lives in' },
    kind: { type: 'string', enum: ['finding', 'suggestion'] },
    severity: { type: 'string', enum: ['blocker', 'major', 'minor'] },
    rule: { type: 'string' },
    summary: { type: 'string' },
    files: { type: 'array', items: { type: 'string' } },
  },
  required: ['key', 'area', 'kind', 'severity', 'summary'],
}

const FINDINGS_SCHEMA = {
  type: 'object',
  properties: {
    findings: { type: 'array', items: FINDING },
    regressions: { type: 'array', items: { type: 'object', properties: { id: { type: 'integer' }, key: { type: 'string' }, fixed: { type: 'boolean' }, note: { type: 'string' } }, required: ['key', 'fixed'] } },
    screensRead: { type: 'integer' },
    boardUrl: { type: 'string' },
  },
  required: ['findings'],
}

const SHOOT_SCHEMA = {
  type: 'object',
  properties: {
    device: { type: 'string' },
    shots: { type: 'array', items: { type: 'object', properties: { route: { type: 'string' }, label: { type: 'string' }, file: { type: 'string' } }, required: ['route', 'label'] } },
    boardUrl: { type: 'string' },
    problems: { type: 'array', items: { type: 'string' } },
  },
  required: ['device', 'shots'],
}

const USERTEST_SCHEMA = {
  type: 'object',
  properties: {
    qaTaskUrl: { type: 'string' },
    boardUrl: { type: 'string' },
    cases: { type: 'array', items: { type: 'object', properties: { title: { type: 'string' }, device: { type: 'string' }, verdict: { type: 'string', enum: ['pass', 'fail', 'skip'] }, note: { type: 'string' }, files: { type: 'array', items: { type: 'string' } } }, required: ['title', 'verdict'] } },
    bugs: { type: 'array', items: { type: 'string', description: 'task url of each bug filed' } },
  },
  required: ['cases'],
}

const FIX_SCHEMA = {
  type: 'object',
  properties: {
    fixed: { type: 'array', items: { type: 'string', description: 'finding key' } },
    skipped: { type: 'array', items: { type: 'object', properties: { key: { type: 'string' }, why: { type: 'string' } }, required: ['key', 'why'] } },
    touchedRoutes: { type: 'array', items: { type: 'string' } },
    touchedFiles: { type: 'array', items: { type: 'string' } },
    commits: { type: 'array', items: { type: 'string' } },
  },
  required: ['fixed', 'skipped', 'touchedRoutes', 'touchedFiles'],
}

const GATE_SCHEMA = {
  type: 'object',
  properties: {
    green: { type: 'boolean' },
    ran: { type: 'array', items: { type: 'string' } },
    failures: { type: 'array', items: { type: 'string' } },
    repaired: { type: 'boolean' },
  },
  required: ['green', 'ran'],
}

const PREPARE_SCHEMA = {
  type: 'object',
  properties: {
    baseUrl: { type: 'string' },
    where: { type: 'string', enum: ['devbox', 'local'] },
    branch: { type: 'string' },
    project: { type: 'string' },
    task: { type: 'string', description: 'vitrinka task id the run is bound to' },
    override: { type: 'object', description: 'parsed .claude/vitrinka-workflows.json or {}' },
    projectType: { type: 'string' },
    problems: { type: 'array', items: { type: 'string' } },
  },
  required: ['baseUrl', 'where', 'branch', 'projectType'],
}

const PUBLISH_SCHEMA = {
  type: 'object',
  properties: {
    boardUrl: { type: 'string' },
    boardSlug: { type: 'string' },
    section: { type: 'string' },
    cards: { type: 'array', items: { type: 'object', properties: { cardId: { type: 'integer' }, route: { type: 'string' }, device: { type: 'string' }, label: { type: 'string' } }, required: ['cardId'] } },
  },
  required: ['boardUrl', 'boardSlug', 'section', 'cards'],
}
// args: { cap?: 2, base?: 'main', pr?: boolean (default true), task?, title?: string }
const A = args || {}
const cap = Math.max(1, Math.min(4, A.cap || 2))
const base = A.base || 'main'

const REVIEW_SCHEMA = {
  type: 'object',
  properties: {
    findings: { type: 'integer' },
    applied: { type: 'integer' },
    remaining: { type: 'array', items: { type: 'object', properties: { file: { type: 'string' }, line: { type: 'integer' }, summary: { type: 'string' }, why: { type: 'string' } }, required: ['file', 'summary'] } },
    commits: { type: 'array', items: { type: 'string' } },
  },
  required: ['findings', 'applied', 'remaining'],
}

const rounds = []
let remaining = []
phase('Review')
for (let round = 1; round <= cap; round++) {
  const review = await agent(withPreamble(
    `Round ${round} of the code loop on this branch against ${base}.\n` +
    `Invoke the code-review skill (Skill tool: code-review) with args \`high --fix\` over the branch diff; let it apply the findings it can. Then commit what it applied (one commit, message "fix(review): round ${round} — <n> findings"). Findings it could not apply — a design call, a trade-off, an uncertain one — are \`remaining\` with why. Return counts, remaining and the commit.`
  ), { label: `review:${round}`, phase: 'Review', schema: REVIEW_SCHEMA })
  if (!review) { log(`code-loop: round ${round} review failed`); break }

  const gate = await agent(withPreamble(
    `Gate round ${round} of the code loop: run the repo's type/build/test gates from CLAUDE.md where CLAUDE.md says they run (the strict TS gates, the Go suite through its wrapper, the unit suites). A failure introduced by ${JSON.stringify(review.commits || [])} you repair and commit; one that predates them is reported. Return green, what ran, failures.`
  ), { label: `gate:${round}`, phase: 'Review', schema: GATE_SCHEMA })
  rounds.push({ round, findings: review.findings, applied: review.applied, remaining: review.remaining.length, green: !!(gate && gate.green) })
  remaining = review.remaining
  log(`code-loop: round ${round} — ${review.findings} findings, ${review.applied} applied, ${review.remaining.length} remaining, gate ${gate && gate.green ? 'green' : 'RED'}`)
  if (review.findings === 0 || (review.applied === 0 && review.remaining.length === review.findings)) break
}

let pr = ''
if (A.pr !== false) {
  phase('PR')
  const opened = await agent(withPreamble(
    `Open the PR for this branch against ${base} through the prm skill (Skill tool: prm) — create and watch, never merge${A.task ? `; the branch is bound to vitrinka task ${A.task}, so the body carries its url` : ''}${A.title ? `; title: ${A.title}` : ''}.\n` +
    (remaining.length ? `Post these unresolved review findings as ONE PR comment for the human, each with file:line and the reviewer's reason it was not applied:\n${JSON.stringify(remaining)}\n` : '') +
    `Return the PR's full https url on the first line and its CI state on the second.`
  ), { label: 'prm', phase: 'PR' })
  pr = (opened || '').split('\n')[0].trim()
}

return { rounds, remaining, pr }
